import * as D from '../packages/domain/src/index.ts';
import { upgradeWorldState } from '../apps/server/src/upgrade-world.ts';
const requireValue=(condition,message)=>{if(!condition)throw Error(message);};
const checks=[];
let world=D.createWorld(73);
const actor=world.entities[D.PLAYER_ID].actor;
actor.agency.attempts.push({id:'old-unresolved',description:'Follow the visible person',normalized:D.normalizeAttempt('Follow the visible person'),manifestRevision:world.moduleManifest.revision,status:'needs-interpretation'});
const identity=world.id,nextId=world.nextId;
upgradeWorldState(world);D.validateWorldModules(world);
let request=world.entities[D.PLAYER_ID].actor.agency.attempts.find(a=>a.id==='old-unresolved');
requireValue(request.targetEntityId===null&&request.mode==='enqueue'&&world.id===identity&&world.nextId===nextId&&!world.entities[D.PLAYER_ID].actor.action,'Unsafe old request upgrade');
const once=JSON.stringify(world);upgradeWorldState(world);requireValue(JSON.stringify(world)===once,'Upgrade not idempotent');
checks.push({name:'old-unresolved-intent-preserved-without-replace-authority',passed:true});
const fulfillment={requested:'Follow until sunset',executableDescription:'Follow until cancelled or target lost; no sunset stop.',verdict:'confirm',supported:['Follow'],omitted:[{requirement:'until sunset',reason:'No stop condition available'}],reason:'Native upgrade exercise, not a live model judgment.'};
D.proposeActionRevision(world,D.PLAYER_ID,'old-alternative',[{id:'follow-choice',actorId:D.PLAYER_ID,type:'follow',targetId:D.NPC_ID}],fulfillment,'replace',actor.planGeneration);
const prior=world.entities[D.PLAYER_ID].actor.agency.attempts.find(a=>a.id==='old-alternative');requireValue(prior?.alternative,'Missing alternative');
const alternative=JSON.stringify(prior.alternative);delete prior.mode;delete prior.targetEntityId;upgradeWorldState(world);D.validateWorldModules(world);
requireValue(prior.mode==='replace'&&prior.targetEntityId===null&&JSON.stringify(prior.alternative)===alternative&&!world.entities[D.PLAYER_ID].actor.action,'Stored revision authority changed');
checks.push({name:'stored-alternative-retains-its-exact-mode-and-commands',passed:true});
const malformed=structuredClone(world);malformed.entities[D.PLAYER_ID].actor.agency.attempts[0].mode='invalid';upgradeWorldState(malformed);let rejected=false;try{D.validateWorldModules(malformed);}catch{rejected=true;}requireValue(rejected,'Malformed present mode silently repaired');
checks.push({name:'malformed-present-state-remains-an-error',passed:true});
console.log(JSON.stringify({scope:'Actual native in-place upgrade and validation on constructed old-shape pending requests; no reset, unit/browser suite or live provider calls.',paidModelCalls:0,checks},null,2));
